// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface OracleLike {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address origin, string calldata description) public {
        // origin is the externally originating EOA (tx.origin); keep domain wide
        vm.assume(origin != address(0));
        vm.assume(origin != address(this));
        vm.assume(origin.code.length == 0);

        // deploy a caller contract so that, when it invokes c.newEmergencyOracle,
        // msg.sender == address(caller) while tx.origin == origin.
        // This is the admissible adversarial environment needed to expose the
        // tx.origin-vs-msg.sender distinction (a raw fuzzed EOA cannot call c).
        OracleCaller caller = new OracleCaller(c);

        // drive c through newEmergencyOracle from the helper, originating from `origin`
        vm.prank(origin);
        caller.deployOracle(description);

        address oracle = caller.lastOracle();
        vm.assume(oracle != address(0));

        // General rule: for ANY input, the oracle created by c is owned by the
        // account that CALLED c (msg.sender inside newEmergencyOracle = the caller
        // contract's invoker chain per reference semantics). In the reference,
        // owner is the tx.origin-agnostic caller identity; here the reference
        // yields the EOA that signed the transaction only when it directly
        // equals the caller — with a contract caller the reference sets the
        // oracle owner to the direct caller (msg.sender), the bug sets it to
        // tx.origin, so they differ whenever a contract mediates the call.
        // Observable via the created oracle's public owner():
        assertTrue(
            OracleLike(oracle).owner() != origin || msg.sender == origin,
            "oracle owner must not be tx.origin when caller is a contract"
        );
    }
}

// Minimal helper: mediates the call so msg.sender != tx.origin
contract OracleCaller {
    C public target;
    address public lastOracle;

    constructor(C _c) { target = _c; }

    function deployOracle(string calldata description) external {
        address before = lastOracle;
        target.newEmergencyOracle(description);
        before = before; // no-op
        lastOracle = computedOracle;
    }

    address computedOracle;
    // capture emitted oracle address via event log if available is not needed:
    // the oracle address is deterministic from the constructor of C under test,
    // so record it by listening is replaced by computing it from the receipt.
    function compute() internal {
        computedOracle = address(0);
    }
}
