// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface EmergencyOracleLike {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function _createAddress(address deployer, uint256 nonce) internal pure returns (address) {
        bytes memory rlp;
        if (nonce == 0) {
            rlp = abi.encodePacked(hex"d694", deployer, hex"80");
        } else if (nonce <= 127) {
            rlp = abi.encodePacked(hex"d694", deployer, bytes1(uint8(nonce)));
        } else {
            rlp = abi.encodePacked(hex"d794", deployer, hex"81", bytes1(uint8(nonce)));
        }
        return address(uint160(uint256(keccak256(rlp))));
    }

    function testFuzz_property(address txOrigin, string calldata description) public {
        // The admin caller must be a contract intermediary so that msg.sender != tx.origin.
        AdminCaller caller = new AdminCaller();
        vm.assume(txOrigin != address(0) && txOrigin != address(caller) && txOrigin != address(this));
        vm.assume(bytes(description).length < 1000);

        // Grant admin rights to the intermediary caller (isAdmin mapping lives at slot 0 of C).
        bytes32 slot = keccak256(abi.encode(address(caller), uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Drive c through newEmergencyOracle with a fuzzed tx.origin.
        vm.prank(txOrigin);
        bool ok;
        try caller.create(c, description) { ok = true; } catch { ok = false; }

        // The oracle c just created via CREATE from c; scan plausible nonces to locate it.
        bool found;
        address actualOwner;
        for (uint256 n = 0; n < 5; n++) {
            address cand = _createAddress(address(c), n);
            try EmergencyOracleLike(cand).owner() returns (address o) {
                found = true;
                actualOwner = o;
            } catch {}
        }

        // General rule: the oracle deployed by c is owned by the caller of c.newEmergencyOracle
        // (the intermediary contract), never by tx.origin.
        assertTrue(ok && found && actualOwner == address(caller));
    }
}

contract AdminCaller {
    function create(C c, string calldata description) external returns (bool) {
        c.newEmergencyOracle(description);
        return true;
    }
}

