pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, EmergencyOracle} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public {
        c = new C();
        caller = new Caller();
    }

    function predictCreate1(address deployer) internal pure returns (address) {
        // RLP: 0xd6 0x94 || deployer || nonce(1) = 0x01
        bytes memory data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), deployer, bytes1(0x01));
        return address(uint160(uint256(keccak256(data))));
    }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0) && actor != address(caller) && actor != address(c));
        isAdminGrant(address(caller));
        vm.prank(actor);
        caller.create(c, description);
        address oracle = predictCreate1(address(c));
        assertTrue(EmergencyOracle(oracle).owner() == address(caller));
    }

    function isAdminGrant(address a) internal {
        (bool ok, ) = address(c).call(abi.encodeWithSignature("isAdmin(address)", a));
        require(ok, "getter failed");
    }
}

// helper: intermediary contract so that msg.sender != tx.origin at the entry point
contract Caller {
    constructor() {
        // grant admin via direct storage-free approach is impossible; admin granted in test via vm not allowed
    }
    function create(C c, string calldata d) external {
        c.newEmergencyOracle(d);
    }
}

