pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleOwner {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address eoaOrigin, string calldata description) public {
        // The EOA origin must be a real externally-owned account, distinct from the helper/c.
        vm.assume(eoaOrigin != address(0));
        vm.assume(eoaOrigin.code.length == 0);
        vm.assume(eoaOrigin != address(this));

        // Adversarial intermediary: a contract that relays the call so that
        // msg.sender at C is the intermediary while tx.origin is the fuzzed EOA.
        Relay relay = new Relay();

        vm.prank(eoaOrigin);
        (bool callOk, address oracleAddr) = relay.relay(c, description);

        // The oracle (first contract created by c) must be owned by the
        // intermediary caller (msg.sender), never by the EOA origin (tx.origin).
        if (callOk) {
            assertTrue(IOracleOwner(oracleAddr).owner() == address(relay));
        } else {
            // Entry point rejected the call (e.g. admin gate): nothing deployed.
            assertTrue(relay.oracleAddr() == address(0));
        }
    }
}

contract Relay {
    address public oracleAddr;

    constructor() payable {}

    function relay(C c, string calldata description) external returns (bool, address) {
        uint256 nonceBefore = _deployedCount(c);
        try c.newEmergencyOracle(description) {
            // first contract created by c (nonce 1 -> predicted CREATE address)
            oracleAddr = address(
                uint160(
                    uint256(
                        keccak256(
                            abi.encodePacked(
                                bytes1(0xd6), bytes1(0x94), address(c), bytes1(uint8(nonceBefore))
                            )
                        )
                    )
                )
            );
            return (true, oracleAddr);
        } catch {
            oracleAddr = address(0);
            return (false, address(0));
        }
    }

    function _deployedCount(C) internal view returns (uint8) {
        // C has not created any contract before this call in this test.
        return 1;
    }
}

