pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface EmergencyOracleOwner {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    AdminCaller intermediary;

    function setUp() public {
        c = new C();
        intermediary = new AdminCaller();
    }

    function testFuzz_property(address eoa, string calldata description) public {
        // wide admissible domain: any EOA that is not the intermediary itself and not zero
        vm.assume(eoa != address(0));
        vm.assume(eoa != address(intermediary));
        vm.assume(eoa != address(c));

        // make the intermediary contract an admin of c (isAdmin is mapping at slot 0)
        bytes32 adminSlot = keccak256(abi.encode(address(intermediary), uint256(0)));
        vm.store(address(c), adminSlot, bytes32(uint256(1)));

        // drive c through the public entry from an EOA via the intermediary contract,
        // so msg.sender == intermediary while tx.origin == eoa (they differ)
        vm.prank(eoa);
        intermediary.create(c, description);

        // the oracle c just deployed is at c's deterministic CREATE address for nonce 1
        address predictedOracle =
            address(uint160(uint256(keccak256(abi.encodePacked(hex"d694", address(c), hex"01")))));

        // GENERAL RULE: the oracle c deploys is owned by the immediate caller
        // (the intermediary, msg.sender), never by tx.origin (the EOA)
        assertTrue(
            EmergencyOracleOwner(predictedOracle).owner() == address(intermediary),
            "oracle owner must be msg.sender of the deploying call, not tx.origin"
        );
    }
}

contract AdminCaller {
    function create(C c, string calldata description) external {
        c.newEmergencyOracle(description);
    }
}

