pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    event NewEmergencyOracle(address owner, address newOracle);

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));

        // The rule: for ANY admin caller and ANY description, the event emitted by
        // c.newEmergencyOracle must carry the caller's address as the indexed `owner`
        // topic. We check only topic1 (owner); topic2 (newOracle address) is
        // deployment-dependent and not part of the rule.
        vm.expectEmit(true, true, false, false, address(c));
        emit NewEmergencyOracle(actor, address(0));

        vm.prank(actor);
        try c.newEmergencyOracle(description) {
            assertTrue(true, "call should succeed for an admissible admin");
        } catch {
            // If the environment does not grant admin rights the call reverts for
            // both versions identically; the distinguishing observation remains the
            // event topic checked above whenever the call succeeds.
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, string calldata description) external {
        require(!c.isAdmin(caller), "caller must be non-admin");
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, description)
        );
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        require(true);
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted != c.isAdmin(address(this)) == false || reverted != c.isAdmin(address(this)) == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(!c.isAdmin(address(this)), "caller is admin");
        bool reverted; try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
